 void BuildingPage(){
  var id=_pageContext!=""?_pageContext:SelectedBuilding;if(!S["projects"].Has(id)){Label(_body,"请选择一座建筑。",23);return;}SelectedBuilding=id;var p=S["projects"][id];var st=G.project_stats(id);var use=S["metrics"].Get("utilization",V.Map()).Get(id,V.Map());
  var identity=CompactTaskCard(_body,"Local building identity");Label(identity,G.project_name(id),25,Domain(p));Label(identity,"T"+p.Get("tier",1).Long+" · "+G.c.operators[p["operator_org"]]["name"].Text+" · "+p["tile"].Text,16,Muted);Illustration(identity,CityIllustrationCatalog.StyleForBuilding(p["def"].Text),95);Label(identity,p.Get("paused",false).Bool?"运营已暂停":p["status"].Text=="construction"?"正在建设":"当前运营",18,p.Get("paused",false).Bool?Gold:Green);
  var upgrading=p.Get("upgrade_job",V.Map()).Count!=0;if(p["status"].Text=="construction"||upgrading){var job=upgrading?p["upgrade_job"]:p["job"];var construction=CompactTaskCard(_body,"Local construction state");Label(construction,upgrading?"升级施工":"新建施工",20,Gold);Meter(construction,"实际完成",job["total"].Double-job["work"].Double,job["total"].Double," CP",Gold);Metric(construction,"尚需材料",F(job["material"].Double));Metric(construction,"共享施工能力",F(Construction.capacity(G))+" CP/月");var priorities=Row(construction,"Local construction priority",44*TextScale);foreach(var value in new[]{-1,0,1}){var priority=value;Button(priorities,value<0?"延后":value>0?"优先":"普通",()=>Command(g=>Construction.set_priority(g,id,priority)));}Button(construction,"全城施工队列",()=>Navigate("construction"));}
  var run=CompactTaskCard(_body,"Local operation bottleneck");Label(run,"运行与瓶颈",20,Blue);Meter(run,"实际运行",use.Get("utilization",p.Get("usage",0)).Double,1,"",Blue);Label(run,use.Get("bottleneck",p.Get("bottleneck","等待实际结算")).Text,17,Gold);Metric(run,"岗位容量",F(st.Get("jobs",0).Double)+" 人");var personnel=Row(run,"Local labor priority",44*TextScale);foreach(var value in new[]{-1,0,1}){var priority=value;Button(personnel,value<0?"让出人手":value>0?"优先供人":"普通供人",()=>Command(g=>g.set_priority(id,priority)));}
  var entries=S["metrics"].Get("activity_ledger",V.Map()).Get(id,V.Arr());Label(run,"最近周期实际活动",18,Blue);if(entries.Count==0)Label(run,"等待实际结算。",16,Muted);foreach(var activity in entries)Label(run,(activity.Get("kind","").Text=="input"?"投入 → ":"产出 ← ")+Resource(activity.Get("resource","").Text)+" "+F(activity.Get("rate",0).Double,3)+" /月"+(activity.Get("kind","").Text!="input"?" · 留 "+F(activity.Get("kept",0).Double,3)+" / 损 "+F(activity.Get("lost",0).Double,3):""),16,activity.Get("kind","").Text=="input"?Gold:Green);
  foreach(var resource in new[]{"food","material","goods"})if(G.stock_cap_for(id,resource)>0)Meter(run,Resource(resource)+"库存",p["inventory"].Get(resource,0).Double,G.stock_cap_for(id,resource),"",Blue);foreach(var kind in G.c.balance["service_kinds"]){var own=S["metrics"].Get("service_links",V.Arr()).Where(x=>x.Get("source","").Text==id&&x.Get("kind","")==kind).Sum(x=>x.Get("people",0).Double);var cap=st.Get("service."+kind.Text,0).Double;if(cap>0)Meter(run,Service(kind.Text)+"实际服务",own,cap," 人",Blue);}
  var slots=CompactTaskCard(_body,"Local building slots");Label(slots,"构筑槽 · 真实安装实例",20,Domain(p));foreach(var slotValue in G.slot_ids(id)){var slot=slotValue.Text;var instanceId=p["slots"].Get(slot,"").Text;var instance=instanceId!=""?S["bonus_instances"][instanceId]:V.Map();var bonus=instance.Get("bonus_id","").Text;Button(slots,G.slot_label(id,slot)+" · "+(bonus!=""?G.c.bonuses[bonus]["name"].Text:"空闲 · 选择蓝图"),()=>Navigate("slot",id+"|"+slot));if(instance.Count>0)Fold(slots,"提供方与实例来源",c=>Raw(c,instance));}
  var residents=S["groups"].Values.Where(x=>x["host"].Text==id).ToArray();if(residents.Length>0){Fold(_body,"本楼住户与实际生活",home=>{var total=residents.Sum(x=>x["count"].Double);Meter(home,"入住 / 住房",total,p["status"].Text=="running"?Math.Max(0,st.Get("housing",0).Double*st.Get("efficiency",1).Double):0," 人",Green);foreach(var key in new[]{"health","happiness","education"})Metric(home,V.Map("health","健康","happiness","幸福","education","教育").Get(key,key).Text,F(residents.Sum(x=>x["count"].Double*x.Get(key,0).Double)/Math.Max(.001,total))+" /100");foreach(var kind in new[]{"food","medical","education","commercial","entertainment"})Meter(home,kind=="food"?"实际口粮":Service(kind),residents.Sum(x=>x["count"].Double*x.Get("living",V.Map()).Get(kind,0).Double),total," 人",Blue);Button(home,"居民与服务名册",()=>Navigate("population"));});}
  Fold(_body,"住户、规则与完整来源",c=>{foreach(var group in residents)Raw(c,group);Raw(c,G.compiled.Get("trace",V.Map()).Get(id,V.Map()));Raw(c,entries);Raw(c,p["history"]);});Fold(_body,"拆除建筑",c=>{Label(c,"支付20通货，住户重新安置；库存转仓不足时记录实际损耗。",16,Muted);Button(c,"拆除（需确认）",()=>Confirm("拆除「"+G.project_name(id)+"」？","支付20通货处理拆除。住户保留并重新安置，库存尝试转仓；仓容不足的实际损耗会记录。",()=>{Command(g=>g.demolish(id),false);SelectedBuilding="";CloseArchive();}));});
