 }
 string _upgradeChoice="";
 void UpgradePage(){
  var id=_pageContext;if(!S["projects"].Has(id)&&S["projects"].Has(SelectedBuilding)){id=SelectedBuilding;_pageContext=id;}if(!S["projects"].Has(id)){Label(_body,"选择一座建筑，比较它的真实升级方向。",24,Gold);WorkspaceActions("返回地图选择建筑",CloseArchive);return;}var p=S["projects"][id];var choices=Development.choices(G,id).Select(x=>x.Text).ToArray();var columns=WorkspaceColumns("Upgrade current candidate comparison",.46f,.54f);var current=columns[0];var candidate=columns[1];Label(current,"当前 · "+G.project_name(id),25,Domain(p));Illustration(current,CityIllustrationCatalog.StyleForBuilding(p["def"].Text),120);Label(current,"T"+p["tier"].Long+" · "+G.c.operators[p["operator_org"]]["name"].Text,18,Muted);Label(current,"身份、运营方、槽轨与已有库存持续保留。",17,Muted);foreach(var resource in new[]{"food","material","goods"})if(G.stock_cap_for(id,resource)>0)Metric(current,Resource(resource)+"库存",F(p["inventory"].Get(resource,0).Double));
  Label(candidate,"选择成长方向",23,Gold);if(!choices.Contains(_upgradeChoice))_upgradeChoice=choices.FirstOrDefault()??"";foreach(var value in choices){var nodeId=value;Button(candidate,(_upgradeChoice==nodeId?"● ":"")+G.c.projects[nodeId]["name"].Text,()=>{_upgradeChoice=nodeId;RenderPage();},_upgradeChoice==nodeId);}if(_upgradeChoice==""){Label(candidate,"当前没有后续升级方向。",18,Muted);WorkspaceActions("返回建筑",()=>Navigate("building",id));return;}
  var node=_upgradeChoice;var view=Development.preview(G,id,node);Label(candidate,view["name"].Text+" · T"+(p["tier"].Long+1),25,Gold);Illustration(candidate,CityIllustrationCatalog.StyleForBuilding(node),120);Metric(candidate,"通货 / 材料",F(view["cost"].Double,0)+" / "+F(view["material"].Double,0));Metric(candidate,"所需施工",F(view["construction_required"].Double)+" CP");Label(candidate,"下一槽："+Catalog.SLOT_NAMES.Get(view["slot"],view["slot"]).Text+" · 施工运营系数 "+F(view["operation_factor"].Double,2),17,Muted);
  Label(current,"当前定义 · 本次变更项目",21,Blue);Label(candidate,"升级定义 · 同项对比",21,Blue);var differences=view["gains"].Concat(view["losses"]).ToArray();if(differences.Length==0){Label(current,"没有数值定义变化。",17,Muted);Label(candidate,"保留当前数值定义。",17,Muted);}foreach(var difference in differences){Metric(current,Stat(difference["stat"].Text),F(difference["before"].Double));Metric(candidate,Stat(difference["stat"].Text),F(difference["after"].Double)+"（"+Signed(difference["delta"].Double)+"）","",difference["delta"].Double>=0?Green:Gold);}
  var baseline=_planner.snapshot(G);var clone=_planner.copy_game(G);clone.s["projects"][id]["upgrade_choice"]=node;clone.s["projects"][id]["upgrade_job"]=V.Map("work",0.0,"total",view["construction_required"],"material",0.0,"cp",true);Development.complete(clone,id);clone.refresh_metrics();var error=Sim.tick(clone,G.c.balance["tick_hours"].Double);
  Label(current,"同一步 · 不升级",21,Blue);Metric(current,"经营净额",F(baseline["metrics"].Get("cashflow",0).Double)+" /月");Metric(current,"供电 / 需求能力",F(baseline["metrics"].Get("energy",0).Double)+" / "+F(baseline["metrics"].Get("energy_need",0).Double));Button(current,"地图 · 现状预测",()=>ShowForecastMap("baseline",baseline));
  Label(candidate,"同一步 · 假定升级完工",21,Blue);if(error==""){Metric(candidate,"经营净额",F(clone.s["metrics"]["cashflow"].Double)+" /月");Metric(candidate,"经营净额变化",Signed(clone.s["metrics"]["cashflow"].Double-baseline["metrics"].Get("cashflow",0).Double)+" /月");Metric(candidate,"供电 / 需求能力",F(clone.s["metrics"]["energy"].Double)+" / "+F(clone.s["metrics"]["energy_need"].Double));Button(candidate,"地图 · 升级完成预测",()=>{_baseline=baseline;_proposal=V.Map("map_snapshot",_planner.display_copy(clone));PublishComparison();ShowForecastMap("proposal",_proposal["map_snapshot"]);});}else Label(candidate,error,17,Gold);
  Fold(current,"当前建筑定义与来源",c=>{Raw(c,G.c.projects[p["def"]]);Raw(c,G.compiled.Get("trace",V.Map()).Get(id,V.Map()));});Fold(candidate,"升级定义与同一步来源",c=>{Raw(c,G.c.projects[node]);if(error=="")Raw(c,clone.compiled["trace"].Get(id,V.Map()));});WorkspaceActions("确认此方向 · 开始升级",()=>Command(g=>Development.start_upgrade(g,id,node)),p["status"].Text!="running"||p["upgrade_job"].Count!=0||S["currency"].Double<view["cost"].Double);WorkspaceActions("返回建筑",()=>Navigate("building",id));WorkspaceHint(G.project_name(id)+" → "+view["name"].Text+"\n即付 "+F(view["cost"].Double,0)+" 通货 · 施工需 "+F(view["material"].Double,0)+" 材料 / "+F(view["construction_required"].Double)+" CP");
 }
 void SlotPage(){var parts=_pageContext.Split('|');if(parts.Length<2||!S["projects"].Has(parts[0]))return;var id=parts[0];var slot=parts[1];var p=S["projects"][id];var iid=p["slots"].Get(slot,"").Text;var rack=Card(_body,G.project_name(id)+" / "+G.slot_label(id,slot),"安装消耗一份真实副本；重签只改变合同组织，原提供方记录保留。",Blue);if(iid!=""){var instance=S["bonus_instances"][iid];var bid=instance["bonus_id"].Text;Label(rack,G.c.bonuses[bid]["name"].Text,25,Gold);Label(rack,"原提供方 "+G.c.operators[instance["provider_org"]]["name"].Text+" · 合同组织 "+G.c.operators[instance.Get("contract_org",instance["provider_org"])]["name"].Text,17,Muted);var actions=Row(rack);Button(actions,"重签为本楼自营 · "+F(G.c.balance["recontract_cost"].Double,0),()=>Command(g=>g.recontract(id,slot)));Button(actions,"拆下当前方案",()=>Command(g=>g.clear_slot(id,slot)));Fold(rack,"已安装规则与历史",c=>{Raw(c,instance);Raw(c,Rules.bonus_rules(G,bid,Math.Max(1,Bonus.active_count(G,bid,"building",id))));});}else Label(rack,"当前为空槽。",20,Muted);
  foreach(var bidValue in Rules.ids(S["block"]["bonus_wallet"])){var bid=bidValue.Text;var license=S["block"]["bonus_wallet"][bid];if(license.Get("charges",0).Long<=0||Bonus.card(G,bid)["scope"].Text!="building")continue;var card=BonusCard(_body,bid);var eligible=G.bonus_eligible(bid,"building",id,slot,iid);var repeat=Bonus.duplicate_preview(G,bid,"building",id);Label(card,eligible==""?"可安装 · "+repeat["note"].Text:eligible,16,eligible==""?Green:Gold);EffectRows(card,repeat["effects"]);if(eligible==""){var forecast=_planner.compare(G,p["def"].Text,p["tile"].Text,V.Map("bonus_id",bid,"provider_org",p["operator_org"],"slot",slot),id,slot);if(forecast.Get("ok",false).Bool)Metric(card,"同一步安装后经营变化",Signed(forecast["cashflow"].Double)+" /月");}Button(card,"消耗1份副本 · 安装",()=>Command(g=>Bonus.install(g,bid,"building",id,slot)),true,eligible!="");}
 }
